#ifndef CAMPUS_CAMPUS_HPP
#define CAMPUS_CAMPUS_HPP

#include <memory>
#include <string>
#include <vector>

#include "door.hpp"
#include "keyring.hpp"
#include "room.hpp"

namespace campus {

// Owns every room and door. Rooms and doors keep the order they were added in.
class Campus {
public:
    Room& addRoom(std::string name, std::string keyColour = "");
    Door& addDoor(const std::string& a, const std::string& b, std::string lockColour = "",
                  int cost = 1);

    const Room* find(const std::string& name) const;
    std::size_t roomCount() const;
    std::size_t doorCount() const;

private:
    std::vector<std::unique_ptr<Room>> rooms_;
    std::vector<std::unique_ptr<Door>> doors_;
};

// Shortest walk from room `from` to room `to`; see the project brief for the rules.
std::string route(const Campus& c, const std::string& from, const std::string& to);

}  // namespace campus

#endif

