#ifndef CAMPUS_DOOR_HPP
#define CAMPUS_DOOR_HPP

#include <string>

#include "keyring.hpp"
#include "room.hpp"

namespace campus {

// A door joins exactly two rooms. A non-empty lock colour means the door only
// opens for somebody carrying a key of that colour. Walking through it costs cost().
class Door {
public:
    Door(Room* a, Room* b, std::string lockColour, int cost)
        : a_(a), b_(b), lock_(std::move(lockColour)), cost_(cost) {}

    const std::string& lock() const { return lock_; }
    int cost() const { return cost_; }

    Room* other(const Room* from) const { return from == a_ ? b_ : a_; }

    bool passable(const Keyring& ring) const { return lock_.empty() || ring.has(lock_); }

    // "<first room>|<second room>", in the order the door was created.
    std::string label() const { return a_->name() + "|" + b_->name(); }

private:
    Room* a_;
    Room* b_;
    std::string lock_;
    int cost_;
};

}  // namespace campus

#endif

