#ifndef CAMPUS_KEYRING_HPP
#define CAMPUS_KEYRING_HPP

#include <set>
#include <string>

#include "room.hpp"

namespace campus {

// The keys somebody is carrying. Keys are never used up.
class Keyring {
public:
    // Picks up the key held by that room, if it holds one.
    void collectFrom(const Room& r) {
        if (!r.key().empty()) keys_.insert(r.key());
    }

    bool has(const std::string& colour) const { return keys_.count(colour) != 0; }
    std::size_t size() const { return keys_.size(); }

    // Every carried colour, ascending, comma separated. Empty ring -> "".
    std::string list() const {
        std::string out;
        for (const std::string& k : keys_) {
            if (!out.empty()) out += ",";
            out += k;
        }
        return out;
    }

private:
    std::set<std::string> keys_;
};

}  // namespace campus

#endif

