#ifndef CAMPUS_LEDGER_HPP
#define CAMPUS_LEDGER_HPP

#include <cstddef>
#include <sstream>
#include <string>
#include <utility>
#include <vector>

namespace campus {

// A small labelled tally. Only two element types are ever used on this campus.
template <typename T>
class Ledger {
public:
    void record(std::string label, T value) {
        entries_.emplace_back(std::move(label), std::move(value));
    }

    std::size_t size() const { return entries_.size(); }

    // "label=value" per entry, in insertion order, joined by ';'.
    std::string report() const {
        std::ostringstream os;
        bool first = true;
        for (const auto& e : entries_) {
            if (!first) os << ";";
            first = false;
            os << e.first << "=" << e.second;
        }
        return os.str();
    }

    // T{} plus every recorded value, in insertion order.
    T total() const {
        T acc{};
        for (const auto& e : entries_) acc += e.second;
        return acc;
    }

private:
    std::vector<std::pair<std::string, T>> entries_;
};

}  // namespace campus

#endif

