#ifndef CAMPUS_ROOM_HPP
#define CAMPUS_ROOM_HPP

#include <string>
#include <vector>

#include "door.hpp"

namespace campus {

// A room on the campus. A room may hold at most one key, named by its colour;
// an empty colour means the room holds no key.
class Room {
public:
    Room(std::string name, std::string keyColour)
        : name_(std::move(name)), key_(std::move(keyColour)) {}

    const std::string& name() const { return name_; }
    const std::string& key() const { return key_; }

    void attach(Door* d) { doors_.push_back(d); }
    const std::vector<Door*>& doors() const { return doors_; }

    // Names of the rooms on the far side of each attached door, sorted ascending.
    std::vector<std::string> neighbours() const {
        std::vector<std::string> out;
        for (Door* d : doors_) out.push_back(d->other(this)->name());
        std::sort(out.begin(), out.end());
        return out;
    }

private:
    std::string name_;
    std::string key_;
    std::vector<Door*> doors_;
};

}  // namespace campus

#endif

