#include "campus.hpp"

#include <stdexcept>

namespace campus {

Room& Campus::addRoom(std::string name, std::string keyColour) {
    rooms_.push_back(std::make_unique<Room>(std::move(name), std::move(keyColour)));
    return *rooms_.back();
}

Door& Campus::addDoor(const std::string& a, const std::string& b, std::string lockColour,
                      int cost) {
    Room* ra = nullptr;
    Room* rb = nullptr;
    for (auto& r : rooms_) {
        if (r->name() == a) ra = r.get();
        if (r->name() == b) rb = r.get();
    }
    if (!ra || !rb) throw std::runtime_error("addDoor: unknown room");
    doors_.push_back(std::make_unique<Door>(ra, rb, std::move(lockColour), cost));
    Door* d = doors_.back().get();
    ra->attach(d);
    rb->attach(d);
    return *d;
}

const Room* Campus::find(const std::string& name) const {
    for (const auto& r : rooms_)
        if (r->name() == name) return r.get();
    return nullptr;
}

std::size_t Campus::roomCount() const { return rooms_.size(); }
std::size_t Campus::doorCount() const { return doors_.size(); }

// route() is declared in campus.hpp and is not implemented anywhere yet.

}  // namespace campus

