// The specification. Do not modify this file.
#include <iostream>
#include <string>
#include <vector>

#include "campus.hpp"
#include "door.hpp"
#include "keyring.hpp"
#include "ledger.hpp"
#include "room.hpp"

static std::string join(const std::vector<std::string>& v) {
    std::string out;
    for (const std::string& s : v) {
        if (!out.empty()) out += ",";
        out += s;
    }
    return out;
}

int main() {
    campus::Campus c;
    c.addRoom("atrium");
    c.addRoom("gallery");
    c.addRoom("forge", "red");
    c.addRoom("annex");
    c.addRoom("vault");
    c.addRoom("cellar", "blue");
    c.addRoom("tower");

    c.addDoor("atrium", "gallery", "", 1);
    c.addDoor("gallery", "vault", "red", 1);
    c.addDoor("atrium", "forge", "", 2);
    c.addDoor("atrium", "annex", "", 1);
    c.addDoor("annex", "vault", "red", 5);
    c.addDoor("atrium", "cellar", "", 1);
    c.addDoor("vault", "tower", "blue", 1);
    c.addDoor("forge", "cellar", "green", 1);
    c.addDoor("gallery", "cellar", "", 3);

    std::cout << "rooms=" << c.roomCount() << " doors=" << c.doorCount() << "\n";
    std::cout << "gallery.neighbours=" << join(c.find("gallery")->neighbours()) << "\n";
    std::cout << "forge.door=" << c.find("forge")->doors().front()->label() << "\n";

    campus::Keyring ring;
    ring.collectFrom(*c.find("atrium"));
    ring.collectFrom(*c.find("forge"));
    ring.collectFrom(*c.find("cellar"));
    std::cout << "keys=" << ring.list() << " n=" << ring.size() << "\n";

    campus::Ledger<int> costs;
    for (const campus::Door* d : c.find("atrium")->doors())
        costs.record(d->other(c.find("atrium"))->name(), d->cost());
    std::cout << "costs=" << costs.report() << " total=" << costs.total() << "\n";

    campus::Ledger<std::string> words;
    words.record("a", "at");
    words.record("b", "rium");
    std::cout << "words=" << words.report() << " total=" << words.total() << "\n";

    std::cout << "r1=" << campus::route(c, "atrium", "vault") << "\n";
    std::cout << "r2=" << campus::route(c, "atrium", "tower") << "\n";
    std::cout << "r3=" << campus::route(c, "gallery", "cellar") << "\n";
    std::cout << "r4=" << campus::route(c, "vault", "tower") << "\n";
    std::cout << "r5=" << campus::route(c, "atrium", "atrium") << "\n";
    std::cout << "r6=" << campus::route(c, "atrium", "moon") << "\n";
    std::cout << "r7=" << campus::route(c, "cellar", "tower") << "\n";
    std::cout << "r8=" << campus::route(c, "annex", "tower") << "\n";
    return 0;
}
